#include <stdio.h>
#include <stdlib.h>

int next_int(void) {
    int c = getchar();
    while (c <= ' ' && c != EOF) c = getchar();
    int x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    return x;
}

int main(void) {
    int n = next_int();
    int m = next_int();

    int *head = (int *)malloc((n + 1) * sizeof(int));
    int *to = (int *)malloc((2 * m) * sizeof(int));
    int *nxt = (int *)malloc((2 * m) * sizeof(int));
    int *deg = (int *)calloc(n + 1, sizeof(int));
    char *vis = (char *)calloc(n + 1, sizeof(char));
    int *queue = (int *)malloc((n + 1) * sizeof(int));
    int *mark = (int *)calloc(n + 1, sizeof(int));

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    int idx = 0;
    for (int i = 0; i < m; i++) {
        int u = next_int();
        int v = next_int();

        to[idx] = v;
        nxt[idx] = head[u];
        head[u] = idx++;

        to[idx] = u;
        nxt[idx] = head[v];
        head[v] = idx++;

        deg[u]++;
        deg[v]++;
    }

    int timestamp = 0;

    for (int i = 1; i <= n; i++) {
        if (vis[i]) continue;

        int qh = 0, qt = 0;
        queue[qt++] = i;
        vis[i] = 1;

        long long sum_deg = 0;

        while (qh < qt) {
            int v = queue[qh++];
            sum_deg += deg[v];

            for (int e = head[v]; e != -1; e = nxt[e]) {
                int u = to[e];
                if (!vis[u]) {
                    vis[u] = 1;
                    queue[qt++] = u;
                }
            }
        }

        int s = qt;
        long long edges = sum_deg / 2;
        long long complete_edges = (long long)s * (s - 1) / 2;

        if (edges < complete_edges) {
            int v = -1;
            for (int j = 0; j < s; j++) {
                int x = queue[j];
                if (deg[x] < s - 1) {
                    v = x;
                    break;
                }
            }

            if (v != -1) {
                timestamp++;
                for (int e = head[v]; e != -1; e = nxt[e]) {
                    mark[to[e]] = timestamp;
                }

                for (int j = 0; j < s; j++) {
                    int u = queue[j];
                    if (u != v && mark[u] != timestamp) {
                        printf("%d %d\n", v, u);
                        return 0;
                    }
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}
